(window.OHX=window.OHX||{})["deviations"]={"d-artisan-s-touch":{"utility":"Tactical Item","quote":"","summary":["Artisan's Touch is an A-grade Crafting Deviation that produces special materials that can be used to craft Tactical Items. Use it to repair an equipment that is currently equipped."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Mousseville Sweet Factory - Approx. (4241,4918)","Ashenton - Approx. (-6290,4599)","Abandoned Refinery - Approx. (-4105,5278)","Hearst Industries - Approx. (6137,-6025)","Eastern Railway Junction - Approx. (4529,-5333)"],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","High temperature"],"variants":0},"d-atomic-lighter":{"utility":"Tactical Item","quote":"\"A powerful lighter, its heat never wanes. Its flames ignite from the ashes of destruction, gather the dust, and fire is born anew. A continuous cycle.\"","summary":["Atomic Lighter is an A-grade Crafting Deviation that produces special materials that can be used to craft Tactical Items. Throw it to cause a powerful explosion."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 14 - Alternate Reality Research Institute (6925,-1601) - Polluted zone","Level 25 - 73 Source Extraction Point (2859,-1688)"]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Music"],"variants":0},"d-atomic-snail":{"utility":"Consumables","quote":"A little snail about to curl into itself. Rumors tell of a town once upon a time that had become madly obsessed with whirlpools. One would be pulled into the dreamy blue when looking at them for a long time. The continuous flow of color into the hole creates an illusion of \"infinity.","summary":["Atomic Snail is an A-grade Crafting Deviation that produces special materials that can be used to craft Whim Potions. Using the potion will grant the air dash ability."],"obtain":[{"where":"Endless Dreams / Manibus / The Way of Winter","how":["Chance drop from opening Stardust's Advent III crates from Prime Wars."],"spawns":[],"src":"Deviation/Crafting List"},{"where":"Evolution's Call / Prismverse's Clash / RaidZone","how":["Not available in PVP scenarios."],"spawns":[],"src":"Deviation/Crafting List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Found in strongholds."],"spawns":[],"src":"Deviation/Crafting List"}],"abilities":[],"techniques":true,"env":["Electricity","Flowers","Crops"],"variants":0},"d-behemoth":{"utility":"Offense","quote":"Behemoth never stops charging forward. Neither does the rider on his back. -\"Unstoppable!\"","summary":["Behemoth is an A-grade Combat Deviation that does P.ATK DMG. He is a loyal companion for George. He was added to the game on July 9, 2026 with the Version 3.0.1. Update"],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":["Often seen in the Red Sands and Blackheart region."],"spawns":[],"src":"Deviation/Combat List"}],"abilities":["Soaring Dragon: not described on the wiki yet.","Dragon Roaming the World: not described on the wiki yet."],"techniques":true,"env":["Electricity","Red light","Toys"],"variants":0},"d-blackback":{"utility":"","quote":"A loyal companion for Metas.","summary":["Blackback is an B-grade Territory Deviation that was added on April 24, 2025 with the Version 1.5.1. Update. It follows the player character in their territory and assists with sanity restoration."],"obtain":[{"where":"All scenarios","how":["No longer available. (Limited-time \"Otherworldly Encounter\" event that ran from 04/24/2025 - 06/01/2025.)"],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":[],"variants":0},"d-brave-george":{"utility":"Offense","quote":"Brave George never lets go of his sword and shield. Just like his former master --'Charge with me!'","summary":["Brave George is a B-grade Combat Deviation that was added to the game on March 25, 2026 with the Version 2.3.5. Update. He is a loyal companion that can participate in combat."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained by defeating the Forsaken Giant."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 43 - Hiverail Restricted Area (1333,4566)"]}],"abilities":["Gravity Lift: Takes effect after player takes the throw, creating a floating area on the ground.","Combat Assist: Generates a floating area beneath the player, allowing them to freely float in the air at a fixed height. Player Movement Speed +20%, jump speed +2, and become immune to fall DMG and stagger (at ability level 1; the wiki gives no value for higher levels yet)."],"techniques":true,"env":["Electricity","Red light","Toys"],"variants":0},"d-butterfly-s-emissary":{"utility":"Offense","quote":"A tiny paper butterfly, glowing with a rosy hue. The butterfly will guide you when you're lost, comfort you when you're in tears, and protect you when you're in danger. The one who folded the butterfly can't be with you just now, but this butterfly can be with you in her place. *Cherish the buttery [sic], for it will reciprocate in kind*","summary":["Butterfly's Emissary is a B-grade Combat Deviation that marks enemy Weakspots, increasing the damage they receive."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained as part of the prologue for every new character in the tutorial, and is always the first Deviation acquired.","Chance drop in Securement Silo - ALPHA (80,-3599) in Chalk Peak.","The Alpha Institute on the bottom floor of the Empty Monolith at (166,-3706).","The top room near rift anchor in Red Sands.","Rosetta strongholds (very low spawn chance)"],"spawns":[]}],"abilities":["Designated Target: Designate a target to attack with Butterfly's Emissary. Targets in the direction you are facing will be prioritized. If there are no targets in the direction you are facing, surrounding enemies will be targeted.","Auto Attack: Autonomously attacks enemy targets. Marks the enemy's Weakspot upon hit and causes it to take +__% extra Weakspot DMG for 5s."],"techniques":true,"env":["Green light","Flowers"],"variants":2},"d-buzzy-bee":{"utility":"Facility","quote":"A toy car shaped like a bumblebee. It's like a little burst of spring has buzzed into the room. You can almost smell the flowers. A-a-achooo!","summary":["Buzzy Bee is a B-grade Territory Deviation. When placed inside of a Securement Pod in the player character's territory, it will increase the rate at which player-planted crops become mutated."],"obtain":[{"where":"Endless Dream / Manibus","how":["Sunbury Farm","Evergreen Vineyard","Brewery Estate","Citrus County","Sutherland Vineyard"],"spawns":[]}],"abilities":[],"techniques":true,"env":["Music","Flowers","Crops"],"variants":3},"d-by-the-wind":{"utility":"Offense","quote":"A tiny lifeform too pure to be of this Earth. Unblessed children, dissonant chords of the celestial voices, evidence of a shattered whole. You can almost hear them singing, calling their progeny home. They spread their blossoms and open their arms in wait, for time stands with them. But perhaps you can offer them another choice?","summary":["By-The-Wind is an A-grade Combat Deviation that can generate walls of wind that block incoming bullets."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Obtained by participating in a Prime War and opening the reward crate."],"spawns":[],"src":"Deviation/Combat List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Spawns in polluted areas once a player's Sanity percentage hits critical (50%)."],"spawns":[],"src":"Deviation/Combat List"}],"abilities":["Gravity Lift: Takes effect after player takes the throw, creating a floating area on the ground.","Combat Assist: Generates a floating zone beneath the player, allowing them to freely float in the air at a fixed height. Player movement speed +20%, jump speed +2, and become immune to fall DMG and stagger."],"techniques":true,"env":["Electricity","Red light","Blue light","Flowers"],"variants":1},"d-cattiva":{"utility":"Production","quote":"","summary":["Cattiva is an S-grade Territory Deviation that was added on October 30, 2025 with the Version 2.2.0. Update. It works in the territory to gather ores or works at the Mining Platform."],"obtain":[{"where":"All scenarios","how":["No longer available. (Limited-time Palworld Collab Companion Check-in event that ran from 10/30/2025 - 01/21/2026.)"],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":["Electricity","Music","High temperature"],"variants":0},"d-chefosaurus-rex":{"utility":"Production","quote":"Who doesn't love this little green toy dinosaur? He's caring, he's clean, and he's an excellent chef! You never know what it'll pull out of its pocket next.","summary":["Chefosaurus Rex is an S-grade Territory Deviation that assists with cooking. Any food Chefosaurus Rex cooks will gain a 10% boost to effects."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Securement Silo - PHI (5142,-2943) in Iron River"],"spawns":[]}],"abilities":[],"techniques":true,"env":["Red light","Toys","High temperature"],"variants":2},"d-chillet":{"utility":"","quote":"","summary":["Chillet is an S-grade Territory Deviation that was added on October 30, 2025 with the Version 2.2.0. Update. It works in the territory to gather ores or works at the Mining Platform."],"obtain":[{"where":"All scenarios","how":["No longer available. (Limited-time Palworld Collab Companion Check-in event that ran from 10/30/2025 - 01/21/2026.)"],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":["Red light","Crops"],"variants":0},"d-chillet-ignis":{"utility":"","quote":"","summary":["Chillet Ignis is an S-grade Territory Deviation that was added on October 30, 2025 with the Version 2.2.0. Update. It works in the territory to gather ores or works at the Mining Platform."],"obtain":[{"where":"All scenarios","how":["No longer available. (Limited-time Palworld Collab Companion Check-in event that ran from 10/30/2025 - 01/21/2026.)"],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":["Red light","Crops"],"variants":0},"d-director-fox":{"utility":"Production","quote":"","summary":["Director Fox is an A-grade Territory Deviation that was added on October 29, 2025 with the Version 2.2.0. Update."],"obtain":[{"where":"Isles of Abyss (Morphed form, official notes)","how":["Morphed form \"Director Fox - Vacation\": a chance to get it from Drifting Greenhouse (the notes' \"How to Get\" column).","Neither the wiki nor the notes give a location for the ordinary form."],"spawns":[],"src":"o:40780_1317280","morphed":true}],"abilities":[],"techniques":true,"env":[],"variants":0,"morphed":"Director Fox - Vacation"},"d-disco-ball":{"utility":"Consumables","quote":"A colorful disco ball, spinning on its own and radiating intense light. It uplifts the spirit, sending those touched by its light into a frenzy of excitement and euphoria. The ball reminisces about its last wild party, singing its own rock song. Waiting for its fans to return. But the dance hall is no more.","summary":["Disco Ball is a B-grade Crafting Deviation that produces special materials that can be used to craft Whim Potions. Use it to extend other Whim duration."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Found in the loot crate that appears after completing the \"Hale's Moving House\" event, part of the Strange Empty House task starting at (2975,-4783) in Tall Grass Inn.","Chance to spawn at Where Does Disco Go? events.","Chance to spawn next to Greywater Camp (Dayton Wetlands)."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 14 - Alternate Reality Research Institute (6927,-1608) - Polluted zone","Level 25 - Fort Eyrie (3321,-2845)","Level 27 - Sunshine Farm (2891,-307)","Level 43 - Hiverail Restricted Area (1350,4638)"]}],"abilities":[],"techniques":true,"env":["Red light","Blue light","Green light"],"variants":0},"d-doberman":{"utility":"","quote":"A loyal companion for Metas.","summary":["Doberman is an B-grade Territory Deviation that was added on April 24, 2025 with the Version 1.5.1. Update. It follows the player character in their territory and assists with sanity restoration."],"obtain":[{"where":"All scenarios","how":["No longer available. (Limited-time \"Otherworldly Encounter\" event that ran from 04/24/2025 - 06/01/2025.)"],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":[],"variants":0},"d-doctor-raven":{"utility":"Facility","quote":"Doctor Raven is obsessed with studying novelties, and you're his favorite test subject. Claims to have mastered 999 flavors of Medicine. -\"Which one would you like today?\"","summary":["Doctor Raven is an A-grade Territory Deviation that works in the territory to improve Supplies Workbench efficiency. Crafted Healing Syringes have a bonus effect."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance to obtain as a drop from defeating Rainfall Reapers (elite monster). These are the Deviants with umbrellas for heads. Rainfall Reapers are located in the following areas:","Harborside (Broken Delta): At the docks, near the beached ship containing the area's Mystical Crate","Sutherland Chemical Plant (Broken Delta): On a series of catwalks near the blue building at the center of the plant","Greywater Industrial Zone (Iron River): Head to the upper level of the facility and look for the area with pipes and vats","Unmarked Settlement (Chalk Peak): South of Evergreen Vineyard. Follow the road leading southwest and drive past the Vulture-occupied town. There is a settlement there that's infested with deviants."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Music","Low temperature"],"variants":0},"d-dr-teddy":{"utility":"Defense","quote":"A devoted doctor with his trusty medkit. Forever rushing from one emergency to the next. So busy, he's forgotten his own name, voice, and face. But he'll never forget the oath he took.","summary":["Dr. Teddy is an A-grade Combat Deviation that can heal allied deviations and heal or rescue fallen Metas."],"obtain":[{"where":"Evolution's Call / Prismverse's Clash","how":["Chance drop from Securement Silo - THETA (5475,-525)."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 14 - Alkirk (6217,-2632)","Level 22 - Highland (5024,-4562)"]}],"abilities":["Remote Healing: Takes effect after the player takes control and throws. When it hits, there is an instant 50% heal of the target's Max HP. If the target has fallen, revive them immediately. After landing on a target, it will continue to recover and focus on the layer.","Intime Healing: 8% Max HP heal per sec, revives allies."],"techniques":true,"env":["Green light","Toys"],"variants":2},"d-dreamcatcher":{"utility":"Consumables","quote":"A delicate Dreamcatcher, woven from spider ilk, quivers from invisible footsteps. The silk, fragile like an illusion, vanishes in the blink of an eye, making it a harbinger of dreams. Children weave webs in unseen places, in corners, shadows, and your peripheral vision. Meanwhile, a famished mother awaits in the dream, full of anticipation.","summary":["Dreamcatcher is a B-grade Crafting Deviation that produces special materials that can be used to craft Whim Potions. Unleashes a spiderweb trap to bind enemies when you are in danger."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 14 - Ricci Securement Point (6531,-3425)","Level 14 - Mirage Monolith Exclusion Zone (6586,-2959))","Level 14 - Alternate Reality Research Institute (6928,-1601) - Polluted zone","Level 15 - East Blackfell Junction (6047,-3146)","Level 50 - Wishland East (2570,5751)"]}],"abilities":[],"techniques":true,"env":["Blue light","Music","Flowers"],"variants":0},"d-electric-eel":{"utility":"Facility","quote":"A string of large batteries wriggle like a lively eel. When threatened, they emit a powerful electric current. The dangerous world unites them as a group. The more members the greater the energy they can release.","summary":["Electric Eel is a B-grade Territory Deviation that improves the Power of generators."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance of obtaining while Fishing anywhere Fish can be caught (such as the lakes in Broken Delta (4665,-6451) and Red Sands (4665,-2372)); occasionally an Electric Eel is caught instead of a Fish.","During Surge of Fish events."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 12 - Greywater Industrial Zone (4824,-3074)","Level 17 - Rippleby (7479,-3963)","Level 25 - 73 Source Extraction Point (2786,-1657)","Level 27 - Sunshine Farm (2896,-333)","Level 46 - Fiskur Harbor (707,6833)"]}],"abilities":[],"techniques":true,"env":["Blue light","Music","High temperature"],"variants":1},"d-enchanting-void":{"utility":"Offense","quote":"","summary":["Enchanting Void is an S-grade Combat Deviation that enhances Melee Attack while simultaneously penalizing Melee Defense."],"obtain":[{"where":"Endless Dreams / Manibus / The Way of Winter","how":["Completion reward from Securement Silo - THETA."],"spawns":[],"src":"Deviation/Combat List"}],"abilities":["Midnight Maul: After throwing, the player transforms into a panther. In panther form, automatically attack hostile targets, increasing melee damage taken by the attacked targets by 200. Lasts for 20 seconds.","Combat Assist: Continue to focus on the player while in the Black Cat form. When focusing on the player, the player's Movement Speed +10% when holding a Melee Weapon, and recover 10% Max HP when hitting a target with a melee attack."],"techniques":true,"env":["Electricity","Red light","Flowers","Low temperature"],"variants":0},"d-extradimensional-cat":{"utility":"Recovery Boost","quote":"A giant kitty sneaking into your garden. Napping in the sun and rolling about on the lawn. Every hair smells of the sun, like a fluffy cloud.","summary":["Extradimensional Cat is an S-grade Territory Deviation that enjoys itself inside the Territory. Accompanies its owner to sleep to make sure that they're fully energetic the next day."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Deadsville at (5988,-5526), inside the large red house, second floor, children's bedroom.","Meyer's Market at (5755,-6558), inside the warehouse.","Greywater Camp at (5386,-3251), sometimes inside the building next to the Wish Machine, sometimes outside by Severin, occasionally outside the fence.","Tall Grass Inn at (2994,4924), approximately where Lowe sits.","Blackfell at (4121,-1465), on the second floor above Paulines diner."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Toys"],"variants":4},"d-festering-gel":{"utility":"Defense","quote":"A bright yellow semi-gold gel that expands slowly in the air. It greedily assimilates everything it touches. It starts off the size of a fist, but will quickly grow if left unchecked. It hunts by luring its prey to consume it... Doesn't it look delicious?","summary":["Festering Gel is a B-grade Combat Deviation that can participate in combat to transform into Shelter and block enemy attacks."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 7 - Blackfell Oil Fields (5313,-1530)","Level 12 - Greywater Industrial Zone (4837,-3070)","Level 14 - Ricci Securement Point (6528,-3432)","Level 18 - Refinery Pollution Point (5259,-3652)"]},{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Spawns after defeating Ravenous Hunter in Monolith of Greed (5933,-4662).","Chance to spawn outside Victor's home in Rift Space during the prologue.","Chance to obtain as loot after defeating Treant at Gaia Cliff Monolith in Broken Delta."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Red light"],"variants":2},"d-fetch-a-lot-bunny":{"utility":"Materials","quote":"An adventurous bunny rabbit that just loves to wander around the wastes. Forever curious about this strange world. Always popping off, then running off. Would you like to stay for tea?","summary":["Fetch-A-Lot Bunny is a B-grade Territory Deviation that works in the Territory to gather all sorts of Plants."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Red Sands (4897,-2487)","Red Sands (1617,-1017)","Blackheart (2445,-195)","Blackheart (2720,478)","Iron River (4930,-4226)"],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 5 - Blackfell Fallen Zone (4203,-1297)","Level 8 - Evergreen (4339,-2473)","Level 14 - Alkirk (6120,-2609)","Level 29 - White Cliff (3410,1224) - This is a polluted zone."]}],"abilities":[],"techniques":true,"env":["Toys","Flowers","Crops"],"variants":5},"d-flame-essence":{"utility":"Facility","quote":"An ancient creature with eyes half-open, half-shut. The hometown is already beyond reach, so what's the harm in adapting to wherever one is?","summary":["Flame Essence is a B-grade Territory Deviation that increases the production efficiency of the Furnace and Electric Furnace. When activated, furnaces enjoy duration reduction of approximately 25-30%. One Flame Essence can only boost the efficiency of one furnace at a time. For an Electric Furnace the efficiency boost applies to both active formulas."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Spawns inside the container building in Hearst Industries (6074,-5987) Broken Delta Region.","Random chance item in the Loot Crate awarded after defeating The Empty House in Securement Silo - PSI.","Under the transmission tower and behind trains and cars when entering buildings from the South in Broken Delta.","Inside the corner of the main warehouse of Chalk Peak.","In the building, up on the conveyor belt of the Sutherland Chemical Plant (4976,-6194), Broken Delta Region."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":["Spawns throughout Red Sands and Blackheart Region."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Toys"],"variants":3},"d-frog-the-leaper":{"utility":"Consumables","quote":"A tin frog that can wind itself up. Once fully wound, it hops just like a real frog, higher with each bounce. And the higher it jumps, the more damage it causes. Try not to let it lose around the fine china.","summary":["Frog the Leaper is a B-grade Crafting Deviation that produces special materials that can be used to craft Whim Potions. Use it to increase Jump capabilities."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance to spawn near Riddle Spot: Lily Pads; for example in Iron River at (6147,-3359), in Blackheart at (1803,-720), etc.","See the Lily Pads article for a comprehensive list of locations.","Chance to spawn at the car climbing challenge south of Riverhart Harbor.","Chance to spawn on top of stacked cars, near the Fastened Mini Reflex Sight in Iron River.","Chance to spawn near the top of the car climbing challenge at Rotten Manor in the Dayton Wetlands (5944,-4989)."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Toys"],"variants":0},"d-gazocchio":{"utility":"Defense","quote":"An ever-burning lamp that guards its dim glow. When the night snuffs out all stars, there will always be a light left for those in need. Don't go gentle into that good night. Even if it's just a fleeting spark.","summary":["Gazocchio (Deviation) is an S-grade Territory Deviation that will defend the player character's territory from invading enemies."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Can be obtained through completion of Deviation - Gazocchio, one of the tasks given by Lowe in Vena Fjord.","Common loot drop when killing enemies in Wish Land - West."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Blue light","Toys","Flowers"],"variants":0},"d-gingerbread-house":{"utility":"Tactical Item","quote":"Cozy, yet tasty. The sweet scent of gingerbread fills the air as you lay your eyes upon it. A little slice of a life long gone. Why not take a bite, and imagine you live in better times? But be careful. You don't want to upset the lady of the house.","summary":["Gingerbread House is an A-grade Crafting Deviation that produces special materials that can be used to craft special Dishes. Consume it to transform into an object."],"obtain":[{"where":"Isles of Abyss (Morphed form, official notes)","how":["Morphed form \"Gingerbread House - Oceanic Cottage\": a chance to get it from Calamity Tower (the notes' \"How to Get\" column)."],"spawns":[],"src":"o:40780_1317280","morphed":true},{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained by completing the Morphic Decoy task, given by Lowe in Greywater Camp (5432,-3298).","Chance loot in Morphic Crates and houses throughout Nalcott."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 37 - Mousseville (5327,4594)","Level 37 - Mousseville Sweet Factory (4266,4917)"]}],"abilities":[],"techniques":true,"env":["Red light","High temperature","Crops"],"variants":0,"morphed":"Gingerbread House - Oceanic Cottage"},"d-growshroom":{"utility":"Gardening","quote":"A silent Mushroom that gives its spores to the harsh world. Memory shattered, civilization silenced. Only the soil responds resolutely.","summary":["Growshroom is an A-grade Territory Deviation that works inside the Territory. Can proactively plant and harvest."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash / Deviation: Survive, Capture, Preserve / RaidZone","how":["Chance to receive when harvesting wild Mushrooms found all over Nalcott, as well as from Mushrooms planted in Loamy Soil or a Planter Box in the player's Territory.","(Deviation: SCP scenario only) Growshrooms are buried in the middle of wild mushroom patches."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Green light","High temperature"],"variants":3},"d-grumpy-bulb":{"utility":"Offense","quote":"A putrid plant that emits a foul stench. Protected by an odor potent enough to drive a person to madness, they thrive in the Stardust-ridden soil. If nothing wants to get too close... Does that mean standing close to one of these plants is a pretty safe place to be?\"","summary":["Grumpy Bulb is an A-grade Combat Deviation that can participate in combat to disrupt enemy threat, making them attack each other. Deals AoE Status DMG and disrupts aggro."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Obtained by harvesting a Deviated Onion."],"spawns":[],"src":"Deviation/Combat List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Often seen in Iron River. Usually buries itself in the ground."],"spawns":[],"src":"Deviation/Combat List"}],"abilities":["Garlicify: Takes effect upon being thrown by a player. Deals AoE Status DMG upon hit and disrupts the aggro of units in the area for 10s.","Autonomous Attack: Cannot move. Continuously attracts the aggro of nearby hostile units."],"techniques":true,"env":["Flowers","High temperature","Crops"],"variants":0},"d-h37":{"utility":"Materials","quote":"A little round robot, with the most adorable ears. What is it planning? What is it thinking? Is it a good luck charm? Or an omen of despair?","summary":["H37 (Deviation) is an A-grade Territory Deviation that enters strongholds occupied by the enemy and collects resources from their Storage Crates."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["H37 (Deviation) is part of the Realm of Nightmares tasks, she can be found at (5321,-3802) near Refinery Pollution Point, on the second floor inside a small corrugated metal building.","Obtained by completing the side task Fragments of a Memory which ends at her final destination in Greywater Camp at (5375,-3235|type=NPC|page=H37 (NPC)).","Chance of drop from optional boss in Securement Silo - ALPHA in Chalk Peak."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 12 - Greywater Industrial Zone (4812,-3055)","Level 17 - Rippleby (5026,-3684)","Level 18 - Refinery Pollution Point (7434,-3996)"]}],"abilities":[],"techniques":true,"env":["Electricity","Toys","Music"],"variants":0},"d-harveseed":{"utility":"Consumables","quote":"A pulsing red seed, the earth gently stirs with it. We'll be inspired, grow strong, and thrive with out friends. Brave ones become stronger, patient ones more resilient, delicate ones more beautiful. We won't stop renovating this world. The seed is red, the roots are black, the blossoms are white. Everything else will turn to green.","summary":["Harveseed is an A-grade Crafting Deviation that can participate in combat to periodically release blazing energy rays, which attack all nearby enemies, inflicting continuous Burn DMG."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance to obtain after defeating Treant at Gaia Cliff Monolith in Broken Delta."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 5 - Blackfell Fallen Zone (4295,-1324)","Level 8 - Evergreen (4352,-2471)"]}],"abilities":[],"techniques":true,"env":["Flowers","High temperature","Crops"],"variants":0},"d-hug-in-a-bowl":{"utility":"Consumable","quote":"Just a regular old bowl... Or is it? A pinch of frustration, a dash of love. That's life, you suppose. You take a deep breath and are reminded, inexplicably, of home.","summary":["Hug-in-a-Bowl is a B-grade Crafting Deviation that produces special materials that can be used to craft special Dishes. Consume to fully recover Sanity."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained by crafting Hug-in-a-Bowl (Food) on an Electric Stove; chance is significantly increased when Deviated Peppercorn is used. (If the deviation is obtained, Hug-in-a-Bowl (Food) will not be obtained from the same crafting queue on the Electric Stove.)"],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 5 - Evergreen (4425,-2469)","Level 25 - Highland (5088,-4542)","Level 37 - Mousseville (5343,4583)","Level 37 - Mousseville Sweet Factory (4273,4960)"]}],"abilities":[],"techniques":true,"env":["Flowers","Crops"],"variants":1},"d-hydronaut-fish":{"utility":"Facility","quote":"A solitary fish, leaving its school to walk onshore. Wisdom is both a blessing and a curse. The world it knew can no longer tolerate fools, but does the sea still have a place in its dreams?","summary":["Hydronaut Fish is an A-grade Territory Deviation that can work in the territory to gather Sea Water, or operate a water purification facility to get fish occasionally."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Completion reward for Securement Silo - EX1 in Onyx Tundra.","After proceeding with the Main Task to Whalebone, complete Lowe's task to obtain one."],"spawns":[],"src":"Deviation/Territory List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Often seen near northern rivers."],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":["Blue light","Toys","Flowers"],"variants":0},"d-ice-pot":{"utility":"Tactical Item","quote":"A flawless crystal, carved into an eternal vessel. Inside, it holds glaciers enough to fill the entire world. What's outside reflects what's within, perfectly balanced. Whatever you do, do not turn it upside down.","summary":["Ice Pot is a B-grade Crafting Deviation that produces special materials that can be used to craft Tactical Items. Use to make large ice cubes."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance to receive upon completion of Securement Silo - EX1 (2144,-6503) in Chalk Peak."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 37 - Mousseville Sweet Factory (4265,4957)","Level 43 - TAIGA Containment Center (3570,3907) - Polluted zone","Level 43 - Avalanche Exclusion Zone (226,4671)","Level 46 - Fiskur Harbor (780,6829) - Polluted zone"]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Music"],"variants":0},"d-invincible-sun":{"utility":"Offense","quote":"A caged sun, radiating endless light and heat. From the moment fire was first gazed upon, life has longed to tame it. We struck flint, ignited coal, reshaped steel, forged wings, and sent our wishes to the skies. One day, the stars themselves will rest in our hands.","summary":["Invincible Sun is an A-grade Combat Deviation that can participate in combat to periodically release blazing energy rays, which attack all nearby enemies, inflicting continuous Burn DMG."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 5 - Blackfell Oil Fields (5355,-1558)","Level 27 - Sunshine Farms (2803,-299)"]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Toys","High temperature"],"variants":1},"d-labrador":{"utility":"","quote":"A loyal companion for Metas.","summary":["Labrador is an B-grade Territory Deviation that was added on April 24, 2025 with the Version 1.5.1. Update. It follows the player character in their territory and assists with sanity restoration."],"obtain":[{"where":"All scenarios","how":["No longer available. (Limited-time \"Otherworldly Encounter\" event that ran from 04/24/2025 - 06/01/2025.)"],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":[],"variants":0},"d-lethal-rabbit":{"utility":"Materials","quote":"An ice-cold assassin, deadly in its precision. No delay, no hesitation. You will never see a trace of it at work, nor see any mess on its clothes. The secret of the blade is to always be one step ahead.","summary":["Lethal Rabbit is an A-grade Territory Deviation that works inside the Territory. Can hunt animals and bring back Leather and Meat."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance random award given from killing and harvesting Rabbits in the wild."],"spawns":["Level 5 - The hills just outside Deadsville at (6245,-5350).","Level 8 - All of Heart Island at (7900,-5640).","Level 43 - The flora patch near Evergreen at (4633,-2427)."]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Low temperature"],"variants":0},"d-logging-beaver":{"utility":"Materials","quote":"A diligent worker, he's even got his own hard hat. He'll complete every job on time, and within budget. Just don't try and make him do overtime. You got it?","summary":["Logging Beaver is an A-grade Territory Deviation that works within the Territory to gather Wood or work at the Logging Platform."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Chance spawn near the docks, south of Meyer’s Market.","Chance spawn near the docks, south of Chalk Peak (2153, -7029)."],"spawns":[],"src":"Deviation/Territory List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Found anywhere in the wilderness."],"spawns":[],"src":"Deviation/Territory List"},{"where":"Securement Silo drop","how":["Listed as a Deviation reward on the Securement Silo - ALPHA page."],"spawns":[],"src":"Securement Silo - ALPHA"}],"abilities":[],"techniques":true,"env":["Electricity","Music","Crops"],"variants":1},"d-lonewolf-s-whisper":{"utility":"","quote":"A pale canine carcass, hunger seeping from its marrow. An endless craving, an insatiable thirst. He who feeds the wolf will inevitably succumb, and join the pack himself. They grow, they feast, and they drive themselves to extinction in a fit of ravenous rage. With nothing left to devour, they can only gnaw upon their own skeletal remains.","summary":["Lonewolf's Whisper is an A-grade Combat Deviation that can participate in combat. Will transform into a black wolf and attack enemies."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtainable as a reward for defeating Shadow Hound (aka \"Rabizex\") at Monolith of Thirst in Chalk Peak."],"spawns":[]}],"abilities":["Designated Target: Designate a target to attack with Lonewolf's Whisper. Targets in the direction you are facing will be prioritized. If there are no targets in the direction you are facing, surrounding enemies will be targeted.","Auto Attack: Autonomously attacks enemy targets and attracts the aggro from nearby enemies. When a target dies, it spawns a clone. Increases Weapon DMG received by the attacked target by 21.6%."],"techniques":true,"env":["Electricity","Red light","Low temperature"],"variants":1},"d-masonic-pyramid":{"utility":"Consumables","quote":"A black stone pyramid shifting from improbable shape to improbable shape. An invitation, a key, a strange door. Touch it, and unlock the narrow confines of the self. A symbol of human courage from the not-so-distant past.","summary":["Masonic Pyramid is a B-grade Crafting Deviation that produces special materials that can be used to craft Whim Potions. Use it to become invisible or spot hiding enemies."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 14 - Mirage Monolith Exclusion Zone (6526,-2952)","Level 21 - Forsaken Monolith Danger Zone (1982, -1449)","Level 43 - Tundra Exclusion Zone (2866,4629)","Level 43 - Avalanche Exclusion Zone (208,4676)"]}],"abilities":[],"techniques":true,"env":["Electricity","Blue light","Music","High temperature"],"variants":0},"d-mini-feaster":{"utility":"Offense","quote":"","summary":["The Mini Feaster is an S-grade Combat Deviation that will mark enemies, or summon tentacles to attack them."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Rewarded for completion of the Lord of the Quest task given by Lowe.","High chance reward for Mist Zone event completion."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Red light","Toys","Music"],"variants":1},"d-mini-wonder":{"utility":"Defense","quote":"A cold, black hole of a heart. Black is the color of entropy. When all existences lose their boundaries, all colors blend into one. After an immeasurable amount of light and heat, what remains darkness. \"All matter that has form shall die.\" So live well while we still have the right to live well.","summary":["Mini Wonder is an S-grade Combat Deviation that can participate in combat to absorb flying bullets toward its owner."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained by completing Lowe's Other World Traveler task in Blackfell.","Chance to obtain when crafting Vortex Generator grenades at a Synthesis Bench."],"spawns":[]}],"abilities":["Designated Target: Designate a target to be buffed by the Mini Wonder. Can only target allied targets.","Bullet Absorption: Absorbs bullets within a certain radius and"],"techniques":true,"env":["Red light","Blue light"],"variants":1},"d-mr-wish":{"utility":"Offense","quote":"A cuddly alpaca, known at all as \"the wise and wonderful Mr. Wish.\" Mr. Wish claims he can grant anyone's wish, as long as they meet the following 3 conditions: 1. The wish must be fun, and Mr. Wish gets the final say on what is \"fun.\" 2. You can't repeat someone else's wish. 3. Mr. Wish will fulfill your wish in whatever manner he pleases. And don't take too long about it! Mr. Wish won't wait around forever.","summary":["Mr. Wish is an S-grade Combat Deviation."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Chance loot from the keycard room in Silo Sigma."],"spawns":[],"src":"Deviation/Combat List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Obtainable only through Deviation fusion."],"spawns":[],"src":"Deviation/Combat List"},{"where":"Securement Silo drop","how":["Listed as a Deviation reward on the Securement Silo - SIGMA page."],"spawns":[],"src":"Securement Silo - SIGMA"}],"abilities":["Rapid Fire: Launch a burst at enemies near the crosshair or nearby hostile targets, marking them with The Bull's Eye effect.","Auto Attack: Automatically attacks hostile targets."],"techniques":true,"env":["Electricity","Red light","Toys","Music","Flowers"],"variants":1},"d-nutcracker":{"utility":"Defense","quote":"A brave soldier stands firm at his post. Following every order, never forgetting his mission. Never show the enemy mercy.","summary":["Nutcracker is an A-grade Territory Deviation that works within the Territory to defend it from invading enemies. There are 5 normal, 3 advanced and 1 rare Nutcracker."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Can be obtained after defeating The Forsaken Giant Mensdevoran in Forsaken Monolithe at (1977,-1400) in Red Sands.","(NORMAL and HARD difficulty servers only) Can be obtained during an H37 event on the regular event tab screen. Collect cultivation essence and use them to get a variety of rewards including shiny variants.","To participate in the event, hit H37 during phase 4 of the season (player character should be at least level 30 or higher)."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 32 - Fort Obsidian (5540,3269)","Level 43 - Hiverail Restricted Area (1295,4226)"]}],"abilities":[],"techniques":true,"env":["Electricity","Green light","Toys"],"variants":0},"d-orb-lightning":{"utility":"Tactical Item","quote":"A lively cloud of lightning, flashing and sparking with wisdom. The point of existence is more than to merely exist.","summary":["Orb Lightning is a B-grade Crafting Deviation that produces special materials that can be used to craft Tactical Items. When thrown, the performance of turrets in the area will be increased."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Alpha Institute (165,-3708); on the bottom floor of Empty Monolith.","Alternate Reality Research Institue (6927,-1805); on the second-subfloor of the south wing in a large safety deposit box room.","Gaia Military Base (3061,-5851); in a room at the north side of the base.","73 Source Extraction Point (2922,-1581)"],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity"],"variants":0},"d-paper-doll":{"utility":"Materials","quote":"A normal Paper Doll, small in size yet full of vitality. The courtyard changed into a strange environment after an incidental nap. He must be cautious, and become more sturdy and tough in order not to be knocked down in this cruel new world. Until he meets a new friend that can be relied on and is worthy of his trust. Together, they will keep surviving so that they can return to the world of their memories, and be reunited with the people who matter to them.","summary":["Paper Doll is a B-grade Territory Deviation that collects materials for use in a Disassembly Bench, improves loot from defeated Deviants, and will repair damaged walls and floors."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 7 - Blackfell Oil Fields (5325,-1564)","Level 14 - Alkirk (6132,-2615)","Level 15 - Refinery Pollution Point (5248,-3701)","Level 32 - Fort Obsidian (5543,3242)"]}],"abilities":[],"techniques":true,"env":["Red light","Toys","Flowers"],"variants":2},"d-party-monkey":{"utility":"Facility","quote":"A revolting instrument that always has malicious intent. It is unable to read the mood around it and cannot hide its intentions, so it ends up being an irritant. Who could derive fun from it?","summary":["Party Monkey (Deviation) is a B-grade Crafting Deviation that produces special materials and can repair its own replicas. It will attract the threat of nearby monsters."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 5 - Blackfell Fallen Zone","Level 17 - Rippleby","Level 25 - Fort Eyrie","Level 50 - Wish Arena"]}],"abilities":[],"techniques":true,"env":["Music","High temperature"],"variants":0},"d-polar-jelly":{"utility":"Offense","quote":"A happy little jelly, bobbing along without a care in the world. A powerful life force, it can regenerate most physical damage. No scars, no pain, she laughs in the face of death. But wounds are memories, pain is wisdom, and life is a journey that must end in death. A life without these things... what can it mean?","summary":["Polar Jelly is an A-grade Combat Deviation that applies Knockback and AOE Frost DMG."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained during Cargo Scramble events (confirm location Evergreen around (4320,-2425)), whenever you become \"chosen\" there is a chance to be awarded Polar Jelly. High level events taking place in higher level regions will award a higher level Deviation. (For a comprehensive list of event locations see the Cargo Scramble article.)","Chance reward for completing Securement Silo - PHI in Iron River."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":["Spawns throughout the Agate Tundra and Vena Fjord regions.","Can also be caught while fishing in cold waters in the North (Agate Tundra and Vena Fjord regions.)"],"spawns":[]}],"abilities":["Frostlash: Upon being thrown, it knocks back enemies nearby the target and forms a new fortification.","Auto Attack: Continuously deal Frost Status DMG to surrounding enemies and force them to move toward you. Increases Frost DMG received by surrounding targets by 36.0%. If Frost Vortexes are formed inside the radius, create additional Ice Spikes."],"techniques":true,"env":["Electricity","Blue light","Low temperature"],"variants":2},"d-pup-buddy":{"utility":"Consumables","quote":"A tiny toy balloon dog happily floats in the air. Dogs are born to be companions for children. The dog can fly and can make friends fly too. The dog loves being a balloon, loves friends, and loves humans. Come play with the little dog.","summary":["Pup Buddy is an A-grade Crafting Deviation that produces special materials that can be used to craft Whim Potions. Use it to increase Load capabilities."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Blackfell Fallen Zone (4307,-1323)","Blackfell Oil Fields (5586,-1268)","Evergreen (4335,-2410)"],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 25 - Fort Eyrie (3234,-2841)","Level 29 - White Cliff (3424,1216)"]}],"abilities":[],"techniques":true,"env":["Green light","Toys","Music"],"variants":1},"d-pyro-dino":{"utility":"Attack","quote":"","summary":["Pyro Dino is an S-grade Combat Deviation that increases Blaze DMG and applies Explosion."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Chance loot from Silo Phi seepage zone."],"spawns":[],"src":"Deviation/Combat List"},{"where":"Securement Silo drop","how":["Listed as a Deviation reward on the Securement Silo - PHI page."],"spawns":[],"src":"Securement Silo - PHI"}],"abilities":["Designated Target: Designate a target to attack with Pyro Dino. Targets in the direction you are facing will be prioritized. If there are no targets in the direction you are facing, surrounding enemies will be targeted.","Autonomous Attack: Autonomously attacks enemy targets. Increases target Blaze DMG received by 24.5%. When attacking targets affected by Burn, cause Explosion 1 time."],"techniques":true,"env":["Green light","Toys","High temperature"],"variants":0},"d-rain-man":{"utility":"Rain Maker","quote":"A solitary cloud with a deep lake for a heart. There is no end to the game of hide-and-seek--no one remembers to seek him anymore. The sky is overcast, memories dim. Today is another day of talking to the weeds.","summary":["Rain Man is an A-grade Territory Deviation that works inside the Territory. Can cause a rainfall around him to help crops grow."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance to obtain as a drop from defeating Rainfall Reapers (elite monster). These are the Deviants with umbrellas for heads. Rainfall Reapers are located in the following areas:","Harborside (Broken Delta): At the docks, near the beached ship containing the area's Mystical Crate","Sutherland Chemical Plant (Broken Delta): On a series of catwalks near the blue building at the center of the plant","Greywater Industrial Zone (Iron River): Head to the upper level of the facility and look for the area with pipes and vats","Unmarked Settlement (Chalk Peak): South of Evergreen Vineyard. Follow the road leading southwest and drive past the Vulture-occupied town. There is a settlement there that's infested with deviants."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Blue light","Low temperature"],"variants":1},"d-rebecca":{"utility":"Deviant Energy Recovery","quote":"","summary":["Rebecca is an S-grade Territory Deviation that can summon the avatar of \"herself\" to comfort and soothe other Deviations."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Chance spawn after completing the LEA Research Lab raid."],"spawns":[],"src":"Deviation/Territory List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Not found in regular drops. Obtainable only through Deviation fusion."],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":["Green light","Toys","Flowers"],"variants":1},"d-shattered-maiden":{"utility":"Offense","quote":"A shy young girl who has her blushing face covered. Will anyone notice her expression? Will anyone notice her thoughts? She wants to try and make new friends today too.","summary":["Shattered Maiden is a Combat Deviation that can participate in combat, fearing and freezing enemies. Inflicts Slowdown, Chained, and increases Explosion DMG."],"obtain":[{"where":"Isles of Abyss (Morphed form, official notes)","how":["Morphed form \"Shattered Maiden - Sailor Suit\": a chance to get it from Calamity Tower (the notes' \"How to Get\" column)."],"spawns":[],"src":"o:40780_1317280","morphed":true},{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Guaranteed to spawn by completing Farmside Fright, acquired from Lowe at Tall Grass Inn.","Chance drop in Securement Silo - THETA.","Chance drop after completing any Workshop Defense event."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 15 - East Blackfell Junction (6035,-1677)","Level 21 - Forsaken Monolith Danger Zone (1863,-1513)","Level 25 - 73 Source Extraction Point (2870,-1677)","Level 29 - White Cliff (3411,1220) - This is a polluted zone.","Level 43 - TAIGA Containment Center (3497,3897) - This is a polluted zone."]}],"abilities":["Designated Target: Designate a target to be attacked by the Shattered Maiden. Targets in the direction you are facing will be prioritized. If there are no targets in the direction you are facing, surrounding enemies will be targeted.","Auto Attack: Autonomously moves and attacks. Inflicts Slowdown and Chained to non-boss enemies in front when attacking, also increasing their Explosion DMG received by 40%."],"techniques":true,"env":["Red light","Blue light","Flowers"],"variants":1,"morphed":"Shattered Maiden - Sailor Suit"},"d-snapshot":{"utility":"Offense","quote":"An old camera, its shutter pressed time and time again. It craves to capture landscapes, to leave behind evidence. Its been here, and it will leave proof. It refuses to become a fading memory.","summary":["ZapCam is an A-grade Combat Deviation that can participate in combat to constantly photograph nearby enemies, increasing the Weapon DMG they receive."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 43 - TAIGA Containment Center (3554,3869)","Level 46 - Fiskur Harbor (730,6805)"]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Low temperature"],"variants":1},"d-snow-globe":{"utility":"Tactical Item","quote":"A bottled landscape where pure snowflakes float forever. Even the most beautiful scenery loses its enchantment when it remains unchanged for eternity. Art should not stop in its tracks there.","summary":["Snow Globe is a B-grade Crafting Deviation that produces special materials that can be used to craft Tactical Items. When thrown, targets will become Frozen."],"obtain":[{"where":"Isles of Abyss (Morphed form, official notes)","how":["Morphed form \"Snow Globe - Sunken Treasure\": a chance to get it from Calamity Nest (the notes' \"How to Get\" column)."],"spawns":[],"src":"o:40780_1317280","morphed":true},{"where":"Endless Dream / Manibus","how":["Chance loot for completion of Securement Silo - PSI (2515,-2614)."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 32 - Fort Obsidian (5613,3267)","Level 37 - Mousseville (5342,4594)","Level 43 - Tundra Exclusion Zone (2929,4635)","Level 43 - Hiverail Restricted Area (1290,4682)"]}],"abilities":[],"techniques":true,"env":["Blue light","Low temperature"],"variants":1,"morphed":"Snow Globe - Sunken Treasure"},"d-snowsprite":{"utility":"Offense","quote":"","summary":[],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Completion reward for Securement Silo - Taurus in Onyx Tundra.","After proceeding with the Main Task to Camp Igloo, complete Lowe's task to obtain one."],"spawns":[],"src":"Deviation/Combat List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Obtainable only through Deviation fusion."],"spawns":[],"src":"Deviation/Combat List"}],"abilities":[],"techniques":true,"env":[],"variants":1,"notes":[{"t":"raidrig: Snowsprite is the key Deviation of its Frost Vortex build. Its crystals deal Frost damage and make enemies more vulnerable to Frost. Without a Frost weapon and mods it does very little.","src":["m:raidrig"]}]},"d-soul-summoner":{"utility":"Offense","quote":"","summary":["Soul Summoner is an A-grade Combat Deviation that was added on October 29, 2025 with the Version 2.2.0. Update."],"obtain":[],"abilities":["Auto-Attack: Autonomously attacks enemy targets, dealing Status DMG. Upon hitting, causes the target to take 18.75% to 43.75% increased Weapon DMG (ability levels 1 to 5, from the wiki's level table).","Designated Target: Soul Summoner prioritizes targeting enemies in the direction you are facing. If there are no targets in that direction, it will target a nearby enemy instead."],"techniques":true,"env":[],"variants":0},"d-space-turner":{"utility":"Tactical Item","quote":"This little metallic cube is a mirror of the universe. Give it a twist and see what you find. With each combination, the world shifts, just a little.","summary":["Space Turner is an A-grade Crafting Deviation that produces special materials that can be used to craft Tactical Items. Use it to teleport a teammate to your location."],"obtain":[{"where":"Isles of Abyss (Morphed form, official notes)","how":["Morphed form \"Space Turner - Water Cube\": a chance to get it from Sea Calamity Zone (the notes' \"How to Get\" column)."],"spawns":[],"src":"o:40780_1317280","morphed":true},{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained upon completion of the Dayton Hospital task, which you are given automatically when you near Paul (who is located in the Dayton Warehouse (5657,-4646)).","Chance loot from Mystical Crates."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 14 - Mirage Monolith Exclusion Zone (6585,-2953)","Level 21 - Forsaken Monolith (1913,-1520) - Polluted zone"]}],"abilities":[],"techniques":true,"env":["Blue light","Toys"],"variants":0,"morphed":"Space Turner - Water Cube"},"d-strange-door":{"utility":"Facility","quote":"An unguarded door that links a path which has been split in two. The key has opened the lock, but places are limited. Only two thresholds stand between traveler and destination. But don't look, much less think, of what lies between the thresholds.","summary":["Strange Door is an A-grade Crafting Deviation that produces special materials and can repair its own replicas. Its owner can teleport between different Strange Doors."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Opportunity to secure as part of In The Tall Grass task, which starts with Claire in Tall Grass Inn (must be Lv.30+ before Claire will offer it.)","Opportunity to secure after completing Riddle Spot: Doors located in Iron River (6609,-3678) and Dayton Wetlands (6509,-5230).","Chance to spawn near the puzzle that rewards the Mid Range Optic near Broken Delta.","Chance of spawning in Blackheart Region.","Chance to drop when looting Mystical Crates."],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 43 - Tundra Exclusion Zone (2928,4645)","Level 43 - Avalanche Exclusion Zone (225,4683)"]}],"abilities":[],"techniques":true,"env":["Red light","Blue light","Flowers"],"variants":0},"d-tar-pudding":{"utility":"Production","quote":"A playful little octopus, savoring the richness of the earth. Life always finds unexpected ways forward.","summary":["Tar Pudding is an A-grade Territory Deviation that works within the territory, able to extract crude oil or work in Refining Facilities."],"obtain":[{"where":"Endless Dreams / Evolution's Call / Manibus / Prismverse's Clash / RaidZone / The Way of Winter","how":["Chance drop from Treant at Avalanche Monolith.","Completion reward from Lowe's task from Camp Igloo."],"spawns":[],"src":"Deviation/Territory List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Often seen in Red Sands and Blackheart Region."],"spawns":[],"src":"Deviation/Territory List"}],"abilities":[],"techniques":true,"env":["Blue light","Low temperature"],"variants":0},"d-the-digby-boy":{"utility":"Materials","quote":"These tiny metal automata seem friendly enough, but there's not much going on behind those eyes. Survive, build, replicate, build, replicate, build, replicate... If left to their own devices, would they destroy the whole world just so they could build more of their weird little gizmos?","summary":["The Digby Boy is a B-grade Territory Deviation that works in the territory to gather ores or works at the mining platform."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Can be obtained through the completion of Deviation Expert, one of the initial tasks given by Lowe in Deadsville.","Chance of award from mining Silver Ore. It has been observed that the chances to drop him significantly lower after the first two drops, making the increased odds go on a 4 hour cooldown. It is also guaranteed to drop from the first Tin Ore that the player mines. After that, The Digby Boy can only drop from Silver."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Music"],"variants":4},"d-upper-world-spawn":{"utility":"Tactical Item","quote":"","summary":["Upper World Spawn is an S-grade Crafting Deviation that unlocks the Upper World Protection formula and produces Upper World Feather material, a required material for crafting Upper World Protection tactical items."],"obtain":[{"where":"Endless Dreams / Manibus / The Way of Winter","how":["Not available in PVE scenarios (except SCP)."],"spawns":[],"src":"Deviation/Crafting List"},{"where":"Evolution's Call / Prismverse's Clash / RaidZone","how":["Completion reward from Securement Silo - PSI."],"spawns":[],"src":"Deviation/Crafting List"},{"where":"Deviation: Survive, Capture, Preserve","how":["Not found in regular drops. Obtainable only through Deviation fusion."],"spawns":[],"src":"Deviation/Crafting List"}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Toys","Low temperature"],"variants":1},"d-voodoo-doll":{"utility":"Defense","quote":"An ancient figure that some respect from a distance, and some rush madly to meet. Same form, same cause, the same cause and the same effect--this is half of the secret of witchcraft.","summary":["Voodoo Doll is an A-grade Combat Deviation that can participate in combat, sharing the damage received by its master or possessing enemies so they share the damage its master receives instead."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Spawns in various locations throughout Nalcott, in particular within Vulture strongholds.","Spawns after completing the Carnival of Doom task at the Junkyard (3623, -7019) settlement in the Broken Delta.","Chance to obtain from securement pod in Union Strondholds.","Broken Delta:","Coastside Plaza: Inside the Hospital on 1st floor by red chest. (7286,-4820)"],"spawns":[]}],"abilities":[],"techniques":true,"env":["Red light","Blue light","Toys","Music"],"variants":1},"d-whalepup":{"utility":"Offense","quote":"A powerful wish box that transforms whatever you place inside according to your desires. Wishing is an art. Use it wisely for unimaginable outcomes.","summary":["Whalepup is an A-grade Combat Deviation that was added on October 29, 2025 with the Version 2.2.0. Update."],"obtain":[{"where":"Isles of Abyss (Morphed form, official notes)","how":["Morphed form \"Whalepup - Don't Get Wet\": a chance to get it from Voyagers (the notes' \"How to Get\" column).","Neither the wiki nor the notes give a location for the ordinary form."],"spawns":[],"src":"o:40780_1317280","morphed":true}],"abilities":[],"techniques":true,"env":["Electricity","Blue light","Toys","Music"],"variants":0,"morphed":"Whalepup - Don't Get Wet"},"d-wish-box":{"utility":"Production","quote":"A powerful wish box that transforms whatever you place inside according to your desires. Wishing is an art. Use it wisely for unimaginable outcomes.","summary":["Wish Box is an A-grade Territory Deviation used in the Territory to transform items into something else after digestion."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Chance of reward from defeating and looting Morphic Crates","Purchasable from Severin VII-S2041 (Stellar Planula Shop)"],"spawns":[]},{"where":"Deviation: Survive, Capture, Preserve","how":[],"spawns":["Level 50 - Wish Arena (2598,5749)"]}],"abilities":[],"techniques":true,"env":["Green light","Flowers"],"variants":0},"d-zapamander":{"utility":"Offense","quote":"Zapamander can call forth lightning from the clouds. If the lightning strikes your heart, you'll acquire extreme speed. The storm has been bound, yet its heart remains tethered to the sky.","summary":["Zapamander is an S-grade Combat Deviation that was added on October 29, 2025 with the Version 2.2.0. Update. It can participate in combat by summoning thunderclouds to strike enemies and enhancing electrical damage."],"obtain":[{"where":"Deviation: Survive, Capture, Preserve","how":["Obtainable only through Deviation fusion."],"spawns":[],"src":"Deviation/Combat List"}],"abilities":[],"techniques":true,"env":["Electricity","Red light","Toys","Music"],"variants":2},"d-zeno-purifier":{"utility":"Offense","quote":"","summary":["Zeno-Purifier is an S-grade Combat Deviation that can participate in combat, granting its owner a blink strike ability and attacks enemies with a dark blade."],"obtain":[{"where":"Endless Dream / Evolution's Call / Manibus / Prismverse's Clash","how":["Obtained via the season goals.","Go to phase one season goals and under the \"Challenge\" tab. Requirements: Defeat 200 enemies with a melee weapon.","Chance drop from Weapon Crates."],"spawns":[]}],"abilities":[],"techniques":true,"env":["Red light","Music"],"variants":0},"d-silent-statue-o-079":{"parts":[["Battle skill: Elemental Shift",["Automatically cycles between three keyword effects: Burn, Power Surge, and Frost Vortex. When the battle skill is cast, it emits a spreading wave centered on the target, dealing the corresponding Status DMG and applying the keyword effect."]],["Ultimate: Elemental Resonance",["Summons a Silent Statue to bless Metas. For every elemental keyword effect the enemy receives, the statue gains the corresponding elemental resonance, increasing the Status DMG of the summoner and their teammates within the area. Gaining all three resonances will significantly boost the keyword damage rate."]],["Where to get it",["The Silent Statue can mainly be obtained by participating in The Echo War, and can also be obtained through the Visional Shop (current season) and by opening the Resonance Box."]]],"after":{},"src":["o:40780_1319892","o:40781_1319568"],"stats":[],"features":[],"howto":""},"d-duet":{"parts":[["What it does",["Duet can modify weather effects within the territory in real-time. Both Metas within the territory and placed facilities will be affected by its abilities."]],["Where to get it",["Challenge The Sunken Lord for a chance to obtain the new Deviation \"Duet\"."]]],"after":{},"src":["o:40780_1317280"],"stats":[],"features":[],"howto":""},"d-chaos-rebecca":{"parts":[["Where to get it (Isles of Abyss)",["New Chaos Deviation added: Chaos Rebecca. Metas can obtain it by challenging the Chaos Tower."]]],"after":{},"src":["o:40780_1317280"],"stats":[],"features":[],"howto":""},"d-employee-no-h37-submarine-attitude":{"parts":[["Morphed Deviation",["Employee No. H37 - Submarine Attitude"]],["How to Get (Isles of Abyss)",["Voyagers"]],["Notes",["Participate in the corresponding gameplay for a chance to obtain the above Morphed Deviations.","All the above Morphed Deviations support Deviation Fusion."]]],"src":["o:40780_1317280"],"stats":[],"features":[],"howto":""}};
